            storedMessage.sealedSenderMessage = await this.serializeDirectSealedSenderMessage(storedMessage, storedMessage.ciphertext, storedMessage.messageType, storedMessage.recipientRegistrationId, sealedSender, contentHint);
            storedMessage.sealedSenderCertificateExpiresAt = senderCertificateExpiresAt(sealedSender.senderCertificateBase64);
