        await completeOutgoingMessageIntent(this.storage, intent.clientMessageId, result, {
            syncPending,
        });
        const returned = { ...result, clientTimestamp: intent.clientTimestamp };
        return syncPending ? { ...returned, syncPending: true } : returned;
