        // intent, before any post. Each request of the call meets its deadline.
        let groupEvidence;
        const boundGroupEvidence = () => {
            if (!groupEvidence)
                throw new Error('group send evidence read before bindEvidence');
            return groupEvidence;
        };
        const control = {
            ...(stopSignal && { stopSignal }),
            beforeRequest: () => boundGroupEvidence().check(),
        };
